def test_banned_intent_graph_all_identifiers() -> None:
    for s in BANNED_INTENT_GRAPH_SYMBOLS:
        assert s.isidentifier()

def test_banned_intent_graph_symbols_all_identifiers() -> None:
    for sym in BANNED_INTENT_GRAPH_SYMBOLS:
        assert sym.isidentifier()
        assert sym

def test_banned_intent_graph_symbols_complete_set() -> None:
    expected = {
        "_GraphQueryTerminalMode",
        "_clone_graph_pattern",
        "GraphQueryTerminalIntent",
        "GraphQueryTerminalStep",
    }
    assert BANNED_INTENT_GRAPH_SYMBOLS == expected

def test_banned_intent_graph_symbols_is_frozenset() -> None:
    assert isinstance(BANNED_INTENT_GRAPH_SYMBOLS, frozenset)
    assert "GraphQueryTerminalIntent" in BANNED_INTENT_GRAPH_SYMBOLS

def test_banned_symbols_are_frozensets() -> None:
    assert isinstance(BANNED_VERSIONED_LAZY_SYMBOLS, frozenset)
    assert isinstance(BANNED_INTENT_GRAPH_SYMBOLS, frozenset)

def test_banned_versioned_lazy_all_identifiers() -> None:
    for s in BANNED_VERSIONED_LAZY_SYMBOLS:
        assert s.isidentifier()

def test_banned_versioned_lazy_symbols_all_identifiers() -> None:
    for sym in BANNED_VERSIONED_LAZY_SYMBOLS:
        assert sym.isidentifier()
        assert sym

def test_banned_versioned_lazy_symbols_is_frozenset() -> None:
    assert isinstance(BANNED_VERSIONED_LAZY_SYMBOLS, frozenset)
    assert "_PlanBackedGraphQuery" in BANNED_VERSIONED_LAZY_SYMBOLS

def test_main_unknown_flag_raises_systemexit(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(sys, "argv", ["lint_graph_lazy_sql_plan.py", "--unknown"])
    with pytest.raises(SystemExit):
        main()

def test_main_violations_without_check_returns_zero(
    monkeypatch: pytest.MonkeyPatch,
    capsys: pytest.CaptureFixture[str],
) -> None:
    def _fake_run_checks() -> list[Violation]:
        return [Violation(code="X", file_path="a.py", line_number=1, message="m")]

    monkeypatch.setattr(linter, "run_checks", _fake_run_checks)
    monkeypatch.setattr(sys, "argv", ["lint_graph_lazy_sql_plan.py"])
    assert main() == 0
    capsys.readouterr()

def test_module_docstring_present() -> None:
    assert linter.__doc__ is not None
    assert "graph" in linter.__doc__.lower()

def test_path_constants_are_absolute() -> None:
    for p in (VERSIONED_LAZY_MIXIN, VERSIONED_TRANSACTIONS, GRAPH_LAZY_SQL, INTENT_GRAPH):
        assert p.is_absolute()

def test_path_constants_end_with_py() -> None:
    for p in (VERSIONED_LAZY_MIXIN, VERSIONED_TRANSACTIONS, GRAPH_LAZY_SQL, INTENT_GRAPH):
        assert p.suffix == ".py"

def test_root_resolves_to_repo_root() -> None:
    assert (ROOT / "scripts").is_dir()
    assert (ROOT / "data_layer").is_dir()

def test_versioned_paths_are_inside_root() -> None:
    for p in (VERSIONED_LAZY_MIXIN, VERSIONED_TRANSACTIONS, GRAPH_LAZY_SQL, INTENT_GRAPH):
        assert p.is_relative_to(ROOT), p

def test_violation_has_four_fields() -> None:
    from dataclasses import fields as _dc_fields

    names = {f.name for f in _dc_fields(Violation)}
    assert names == {"code", "file_path", "line_number", "message"}

def test_violation_hashable() -> None:
    v = Violation(code="X", file_path="a", line_number=1, message="m")
    assert hash(v) == hash(
        Violation(code="X", file_path="a", line_number=1, message="m"),
    )

def test_violation_is_hashable() -> None:
    v = Violation("GLSP-001", "f.py", 1, "m")
    s = {v}
    assert v in s

